        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code sc, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 3 DESC", "claim": "Travel-service's GET /travelservice/routes/{tripId} returns 500 in about 11 ms for 2528 requests; other endpoints stay 200."},
