        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_http_response_status_code>=500 THEN 1 ELSE 0 END) e5 FROM normal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "In the normal period travel-service server spans have zero 5xx responses."}
