      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) callee_5xx, round(avg(p.duration)/1e6,1) caller_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' AND c.attr_span_kind='Server' GROUP BY 1,2", "claim": "Travel-plan's calls to route-plan take about 48 s on average, with 84 route-plan 5xx responses."}
      ]
    },
    {
