      "evidence": [
        {"kind": "trace", "sql": "SELECT u.service_name, b.service_name downstream, count(DISTINCT u.trace_id) traces, round(avg(u.duration)/1e6,1) ui_ms_avg, sum(CASE WHEN b.attr_http_response_status_code>=500 THEN 1 ELSE 0 END) downstream_5xx FROM abnormal_traces u JOIN abnormal_traces b ON b.trace_id=u.trace_id WHERE u.service_name='ts-ui-dashboard' AND u.attr_span_kind='Server' AND b.service_name='ts-food-service' AND b.attr_span_kind='Server' GROUP BY 1,2", "claim": "Dashboard food requests in the same traces average about 13 s, with 73 food-service 5xx responses."}
